    c,n=map(int,line.split())
    hist.append((c,n))
# smooth moving sum over +/-10 and find local maxima over 100 counts
vals={c:n for c,n in hist}
sm=[]
for c,n in hist:
    if c<50: continue
    s=sum(vals.get(i,0) for i in range(c-10,c+11))
